async def act(page):
    """
    Plan:
    1. Navigate (relative) to the Manage Products page (/index.php/admin/catalog_product/).
    2. Use accessibility-role-centric selectors (page.get_by_role) to search for the product "Frankie Sweatshirt".
    3. Open the product edit by clicking the product link.
    4. Open the "Associated Products" tab.
    5. Use the Associated Products quick-create flow to create two simple products with Color = Blue and Size = S and M.
    6. Save the parent product.

    Notes about knowledge_base functions: none are available in the provided environment, so none are called.
    All interactions use page.get_by_role() and .select_option() for select elements, as required.
    """
    # 1) Go to Manage Products using a relative URL
    await page.goto("/index.php/admin/catalog_product/")
    await page.wait_for_load_state("networkidle")

    # 2) Try to fill the product name filter. Use accessible role selectors with fallbacks.
    try:
        await page.get_by_role("textbox", name="Name").fill("Frankie Sweatshirt")
    except Exception:
        try:
            # fallback: use the first textbox on the page
            await page.get_by_role("textbox").first.fill("Frankie Sweatshirt")
        except Exception:
            # if no textbox is found, proceed; subsequent search attempt may still work
            pass

    # 3) Click Search (try a few likely button names)
    search_button_names = ["Search", "Find", "Filter"]
    for btn_name in search_button_names:
        try:
            await page.get_by_role("button", name=btn_name).click()
            break
        except Exception:
            continue

    await page.wait_for_load_state("networkidle")

    # 4) Open the product edit page by clicking the product link
    try:
        await page.get_by_role("link", name="Frankie Sweatshirt").first.click()
    except Exception:
        # As a last resort click any link that contains the product name (accessibility-roled link)
        try:
            await page.get_by_role("link").filter(has_text="Frankie Sweatshirt").first.click()
        except Exception:
            # If we cannot click the product, raise so the test fails visibly
            raise

    await page.wait_for_load_state("networkidle")

    # 5) Open the Associated Products tab
    tab_fallbacks = ["Associated Products", "Associated", "Associated Items"]
    tab_clicked = False
    for t in tab_fallbacks:
        try:
            await page.get_by_role("tab", name=t).click()
            tab_clicked = True
            break
        except Exception:
            try:
                await page.get_by_role("link", name=t).click()
                tab_clicked = True
                break
            except Exception:
                continue
    # If no explicit tab role, try a button
    if not tab_clicked:
        for t in tab_fallbacks:
            try:
                await page.get_by_role("button", name=t).click()
                tab_clicked = True
                break
            except Exception:
                continue

    await page.wait_for_load_state("networkidle")

    # Helper to create a simple associated product with Color=Blue and the given size
    async def create_associated_simple(size_label: str):
        # Try to start the quick-create or create-product flow
        create_btn_names = ["Create Product", "Create", "Quick Create", "Create New", "Add New"]
        created = False
        for name in create_btn_names:
            try:
                await page.get_by_role("button", name=name).click()
                created = True
                break
            except Exception:
                continue

        # If we didn't find a named button, try any button that contains Create in its accessible name
        if not created:
            try:
                # find first button and try clicking if its name contains 'Create'
                all_buttons = page.get_by_role("button")
                count = await all_buttons.count()
                for i in range(count):
                    try:
                        btn = all_buttons.nth(i)
                        btn_name = await btn.get_attribute("name")
                        # accessible name may not be exposed via attribute; try clicking heuristically
                        await btn.click()
                        created = True
                        break
                    except Exception:
                        continue
            except Exception:
                pass

        # Wait for quick-create form to appear
        await page.wait_for_load_state("networkidle")

        # Fill name (try explicit accessible Name field, fallback to first textbox)
        try:
            await page.get_by_role("textbox", name="Name").fill(f"Frankie Sweatshirt - Blue - {size_label}")
        except Exception:
            try:
                await page.get_by_role("textbox").first.fill(f"Frankie Sweatshirt - Blue - {size_label}")
            except Exception:
                pass

        # Fill SKU if present
        try:
            await page.get_by_role("textbox", name="SKU").fill(f"frankie-blue-{size_label.lower()}")
        except Exception:
            # try second textbox if present
            try:
                tb = page.get_by_role("textbox").nth(1)
                await tb.fill(f"frankie-blue-{size_label.lower()}")
            except Exception:
                pass

        # Select Color = Blue using combobox(es)
        try:
            # try a combobox with accessible name Color
            await page.get_by_role("combobox", name="Color").select_option(label="Blue")
        except Exception:
            # fallback: try all comboboxes and pick one that accepts Blue
            try:
                comboboxes = page.get_by_role("combobox")
                cb_count = await comboboxes.count()
                for i in range(cb_count):
                    try:
                        cb = comboboxes.nth(i)
                        await cb.select_option(label="Blue")
                        break
                    except Exception:
                        continue
            except Exception:
                pass

        # Select Size
        try:
            await page.get_by_role("combobox", name="Size").select_option(label=size_label)
        except Exception:
            try:
                comboboxes = page.get_by_role("combobox")
                cb_count = await comboboxes.count()
                for i in range(cb_count):
                    try:
                        cb = comboboxes.nth(i)
                        await cb.select_option(label=size_label)
                        break
                    except Exception:
                        continue
            except Exception:
                pass

        # Set Status to Enabled if a combobox exists with that name
        try:
            await page.get_by_role("combobox", name="Status").select_option(label="Enabled")
        except Exception:
            pass

        # Set Visibility if present
        try:
            await page.get_by_role("combobox", name="Visibility").select_option(label="Not Visible Individually")
        except Exception:
            pass

        # Save the simple product (try various common button names)
        save_names = ["Save", "Save Item", "Save & Continue Edit", "Create"]
        for s in save_names:
            try:
                await page.get_by_role("button", name=s).click()
                break
            except Exception:
                continue

        await page.wait_for_load_state("networkidle")

    # Create simple product for sizes S and M
    await create_associated_simple("S")

    # Re-open Associated Products tab if needed before creating the next
    try:
        await page.get_by_role("tab", name="Associated Products").click()
    except Exception:
        try:
            await page.get_by_role("link", name="Associated Products").click()
        except Exception:
            pass

    await page.wait_for_load_state("networkidle")
    await create_associated_simple("M")

    # Finally, save the parent configurable product
    try:
        await page.get_by_role("button", name="Save").click()
    except Exception:
        # fallback variants
        for label in ["Save & Continue Edit", "Save Item"]:
            try:
                await page.get_by_role("button", name=label).click()
                break
            except Exception:
                continue

    await page.wait_for_load_state("networkidle")

